-- zip 310: stock locations, stock movements, transfers (internal and between branches), approval settings, HQ roles. Also created by the server on first use (ensureStockSchema in functions/api/_stock.js, ensureRoles in functions/api/_hq-reports.js).
CREATE TABLE IF NOT EXISTS inv_location (group_id TEXT NOT NULL, location_id TEXT NOT NULL, client_id TEXT NOT NULL, name TEXT NOT NULL, kind TEXT NOT NULL DEFAULT 'store' CHECK (kind IN ('store','warehouse','kitchen','bar','pharmacy','other')), status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','archived')), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, PRIMARY KEY (group_id, location_id)) WITHOUT ROWID;
CREATE UNIQUE INDEX IF NOT EXISTS ux_inv_location_name ON inv_location (group_id, client_id, lower(name));
CREATE TABLE IF NOT EXISTS inv_loc_stock (group_id TEXT NOT NULL, location_id TEXT NOT NULL, code TEXT NOT NULL, name TEXT NOT NULL, unit TEXT NOT NULL DEFAULT 'pcs', unit_cost REAL NOT NULL DEFAULT 0, qty REAL NOT NULL DEFAULT 0 CHECK (qty >= 0), updated_at INTEGER NOT NULL, PRIMARY KEY (group_id, location_id, code)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS inv_movement (group_id TEXT NOT NULL, movement_id TEXT NOT NULL, at INTEGER NOT NULL, kind TEXT NOT NULL, client_id TEXT NOT NULL, location_id TEXT NOT NULL, code TEXT NOT NULL, name TEXT, unit TEXT, qty REAL NOT NULL, xfer_id TEXT, ref TEXT, actor TEXT, reason TEXT, reverses TEXT, PRIMARY KEY (group_id, movement_id)) WITHOUT ROWID;
CREATE INDEX IF NOT EXISTS ix_inv_movement_at ON inv_movement (group_id, at);
CREATE INDEX IF NOT EXISTS ix_inv_movement_loc ON inv_movement (group_id, client_id, location_id, at);
CREATE TABLE IF NOT EXISTS xfer (group_id TEXT NOT NULL, xfer_id TEXT NOT NULL, ref TEXT NOT NULL, internal INTEGER NOT NULL DEFAULT 0, from_client TEXT NOT NULL, from_loc TEXT NOT NULL, to_client TEXT NOT NULL, to_loc TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('pending','approved','rejected','cancelled','dispatching','in_transit','partial','discrepancy','completed')), value REAL NOT NULL DEFAULT 0, notes TEXT, requested_by TEXT, requested_at INTEGER NOT NULL, approved_by TEXT, approved_at INTEGER, dispatched_by TEXT, dispatched_at INTEGER, received_by TEXT, received_at INTEGER, closed_at INTEGER, reject_reason TEXT, reverses TEXT, updated_at INTEGER NOT NULL, PRIMARY KEY (group_id, xfer_id)) WITHOUT ROWID;
CREATE UNIQUE INDEX IF NOT EXISTS ux_xfer_ref ON xfer (group_id, ref);
CREATE INDEX IF NOT EXISTS ix_xfer_status ON xfer (group_id, status, updated_at);
CREATE TABLE IF NOT EXISTS xfer_line (group_id TEXT NOT NULL, xfer_id TEXT NOT NULL, line_id TEXT NOT NULL, code TEXT NOT NULL, name TEXT NOT NULL, unit TEXT NOT NULL DEFAULT 'pcs', unit_cost REAL NOT NULL DEFAULT 0, unit_price REAL NOT NULL DEFAULT 0, qty_req REAL NOT NULL CHECK (qty_req > 0), qty_disp REAL NOT NULL DEFAULT 0, qty_recv REAL NOT NULL DEFAULT 0, qty_damaged REAL NOT NULL DEFAULT 0, qty_missing REAL NOT NULL DEFAULT 0, batch TEXT, expiry TEXT, resolution TEXT, resolved_qty REAL NOT NULL DEFAULT 0, CHECK (qty_disp <= qty_req + 0.000001), CHECK (qty_recv + qty_damaged + qty_missing <= qty_disp + 0.000001), PRIMARY KEY (group_id, xfer_id, line_id)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS xfer_event (group_id TEXT NOT NULL, event_id TEXT NOT NULL, xfer_id TEXT NOT NULL, at INTEGER NOT NULL, actor TEXT, action TEXT NOT NULL, detail TEXT, PRIMARY KEY (group_id, event_id)) WITHOUT ROWID;
CREATE INDEX IF NOT EXISTS ix_xfer_event_x ON xfer_event (group_id, xfer_id, at);
CREATE TABLE IF NOT EXISTS org_seq (group_id TEXT NOT NULL, name TEXT NOT NULL, n INTEGER NOT NULL, PRIMARY KEY (group_id, name)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS org_setting (group_id TEXT NOT NULL, k TEXT NOT NULL, v TEXT NOT NULL, updated_at INTEGER NOT NULL, PRIMARY KEY (group_id, k)) WITHOUT ROWID;
CREATE TRIGGER IF NOT EXISTS no_delete_inv_movement BEFORE DELETE ON inv_movement BEGIN SELECT RAISE(ABORT, 'stock movements are never deleted'); END;
CREATE TRIGGER IF NOT EXISTS no_update_inv_movement BEFORE UPDATE ON inv_movement BEGIN SELECT RAISE(ABORT, 'stock movements are never changed: record a reversal'); END;
CREATE TRIGGER IF NOT EXISTS no_delete_xfer BEFORE DELETE ON xfer BEGIN SELECT RAISE(ABORT, 'transfers are never deleted'); END;
CREATE TRIGGER IF NOT EXISTS no_delete_xfer_line BEFORE DELETE ON xfer_line BEGIN SELECT RAISE(ABORT, 'transfers are never deleted'); END;
CREATE TRIGGER IF NOT EXISTS no_delete_xfer_event BEFORE DELETE ON xfer_event BEGIN SELECT RAISE(ABORT, 'transfer history is append-only'); END;
CREATE TRIGGER IF NOT EXISTS no_update_xfer_event BEFORE UPDATE ON xfer_event BEGIN SELECT RAISE(ABORT, 'transfer history is append-only'); END;
CREATE TRIGGER IF NOT EXISTS no_edit_closed_xfer BEFORE UPDATE ON xfer WHEN OLD.status IN ('completed','rejected','cancelled') BEGIN SELECT RAISE(ABORT, 'a closed transfer cannot be changed'); END;
CREATE TABLE IF NOT EXISTS org_role (group_id TEXT NOT NULL, role_id TEXT NOT NULL, name TEXT NOT NULL, about TEXT, tabs TEXT NOT NULL DEFAULT '[]', is_manager INTEGER NOT NULL DEFAULT 0, template TEXT, status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','archived')), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, PRIMARY KEY (group_id, role_id)) WITHOUT ROWID;
CREATE UNIQUE INDEX IF NOT EXISTS ux_org_role_name ON org_role (group_id, lower(name));
